3	/**
4	 * A helper class for other classes to be able to meaningfully
5	 * communicate errors with the user through message dialogues.
6	 *
7	 * @version 2022.03.02
8	 */
9	public class ErrorThrower
10	{
11	    /**
12	     * Communicates a specific message to the user through a message dialogue.
13	     *
14	     * @param message (String) The message to be passed to the user.
15	     */
16	    public void throwMessage(String message) {
17	        showMessageDialog(null, message);
18	    }
19	}
