1	/**
2	 * An enum that specifies the values and actions of the different
3	 * climate change scenarios to approximate the real scenarios projected by the IPCC.
4	 *
5	 * @version 2022.02.28
6	 */
7	public enum ClimateScenarios
8	{
9	    SCENARIO1("none", 0, 0), SCENARIO2("low", 1, 0.05), SCENARIO3("medium", 2, 0.15), SCENARIO4("high", 3, 0.3);
10	
11	    private final String label;
12	    private double concreteChange;
13	    private final double changePercentage;
14	
15	    /**
16	     * Create an appropriate Climate Scenario
17	     *
18	     * @param label (String) the user-facing name for this scenario
19	     * @param concreteChange (int) hold the actual temperature change value
20	     * @param changePercentage (double) the change percentage that is added to the concreteChange each year
21	     */
22	    ClimateScenarios(String label, int concreteChange, double changePercentage)
23	    {
24	        this.label = label;
25	        this.concreteChange = concreteChange;
26	        this.changePercentage = changePercentage;
27	    }
28	
29	    /**
30	     * @return (String) the user-facing label for this scenario
31	     */
32	    public String getLabel()
33	    {
34	        return label;
35	    }
36	
37	    /**
38	     * Return the scenario whose label matches the given string, defaulting to SCENARIO1 (no change).
39	     *
40	     * @param label (String) the label to look up
41	     * @return (ClimateScenarios) the matching scenario
42	     */
43	    public static ClimateScenarios fromLabel(String label)
44	    {
45	        for (ClimateScenarios s : values()) {
46	            if (s.label.equals(label)) return s;
47	        }
48	        return SCENARIO1;
49	    }
50	    
51	    /**
52	     * @return (int) the concreteChange as a rounded int
53	     */
54	    public int getClimateChangeEffect()
55	    {
56	        return (int) Math.round(concreteChange);
57	    }
58	
59	    /**
60	     * Increases the concreteChange by the changePercentage.
61	     */
62	    public void doClimateChange()
63	    {
64	        concreteChange = concreteChange + (changePercentage * concreteChange);
65	    }
66	}
