1	import java.awt.Color;
2	import java.util.ArrayList;
3	import java.util.HashMap;
4	import java.util.List;
5	import java.util.Random;
6	
7	/**
8	 * Initializing the simulation. It first launches the UI, then builds the appropriate
9	 * objects to run the simulation desired by the user.
10	 *
11	 * IMPORTANT: This is the class that should be called to run the simulation.
12	 *
13	 * @version 2022.03.01
14	 */
15	public class Initializer
16	{
17	    // The default width for the grid.
18	    private static final int DEFAULT_WIDTH = 120;
19	    // The default depth of the grid.
20	    private static final int DEFAULT_DEPTH = 80;
21	    // The default color for plant objects.
22	    private static final Color DEFAULT_PLANT_COLOR = Color.decode("0x006400");
23	    // Default plant name, for now there is just one type of plant so its name is default, this can be changed as the rest of the code is extendable.
24	    private static final String DEFAULT_PLANT_NAME = "plant";
25	    // The default value of if animals' ages must be randomized when thy are created.
26	    private static final boolean RANDOM_ANIMAL_AGE = true;
27	    // The names of available climate change scenarios, derived from the enum to stay in sync.
28	    private static final ArrayList<String> CLIMATE_CHANGE_SCENARIO_NAMES;
29	    static {
30	        CLIMATE_CHANGE_SCENARIO_NAMES = new ArrayList<>();
31	        for (ClimateScenarios s : ClimateScenarios.values()) {
32	            CLIMATE_CHANGE_SCENARIO_NAMES.add(s.getLabel());
33	        }
34	    }
35	    // False of the simulation starts during the day, true if it starts during the night.
36	    private static final boolean DEFAULT_START_TIME = false;
37	    // The list of colors available for animal objects.
38	    private ArrayList<Color> listOfColorsForAnimals;
39	    // The index of the next color from the list used for an animal.
40	    private int idxOfColorToUseNext;
41	    // List of species to evolve in the field.
42	    private List<Species> speciesToEvolveInSimulation;
43	    // To read habitat related data.
44	    private final HabitatCSVReader habitatReader;
45	    // To read animal related data.
46	    private final AnimalCSVReader animalReader;
47	    // To read plant related data.
48	    private final PlantCSVReader plantReader;
49	    // A Random object to handle random behaviours throughout the class.
50	    private static final Random rand = Randomizer.getRandom();
51	    // A graphical view of the simulation.
52	    private SimulatorView view;
53	    // The plant concentration in the habitat created by the user.
54	    private double habitatPlantConcentration;
55	    // The GUIHandler handling the GUI.
56	    private GUIHandler handler;
57	    // Tool to alert user about any potential error.
58	    private ErrorThrower errorThrower;
59	
60	
61	    /**
62	     * Builds an Initializer object and initializes its field.
63	     */
64	    public Initializer()
65	    {
66	        speciesToEvolveInSimulation = new ArrayList<>();
67	        habitatReader = new HabitatCSVReader();
68	        animalReader = new AnimalCSVReader();
69	        plantReader = new PlantCSVReader();
70	        listOfColorsForAnimals = new ArrayList<>();
71	        errorThrower = new ErrorThrower();
72	
73	        populateAnimalColors();
74	        idxOfColorToUseNext = 0;
75	
76	        openGUI();
77	    }
78	
79	    /**
80	     * Opens the GUI with the list of available animals and habitats extracted
81	     * from the files as well as the list of available climate change scenarios.
82	     */
83	    private void openGUI()
84	    {
85	        ArrayList<String> animalChoices = animalReader.getChoicesList();
86	        ArrayList<String> habitatChoices = habitatReader.getChoicesList();
87	        handler = new GUIHandler(this, animalChoices, habitatChoices, CLIMATE_CHANGE_SCENARIO_NAMES);
88	    }
89	
90	    /**
91	     * Create a simulator with the animals, habitat, and climate change
92	     * scenario asked by the user as well as all other necessary objects
93	     * for the simulation to run. The created Simulator is returned.
94	     *
95	     * @param chosenHabitat (String) The name of the habitat chosen by the user.
96	     * @param animalsToCreate (HashMap<String, Integer>) Keys are the animals' names and values are the number of each animal we need to create.
97	     * @param scenarioName (String) The name of the climate change scenario to implement in the simulation.
98	     * @return (Simulator) The created simulator.
99	     */
100	    public Simulator initializeSimulation(String chosenHabitat, HashMap<String, Integer> animalsToCreate, String scenarioName)
101	    {
102	        SimulationStep simulatorStepCounter = new SimulationStep();
103	        Field field = new Field(DEFAULT_DEPTH, DEFAULT_WIDTH);
104	        ClimateScenarios chosenClimateChangeScenario = createChosenClimateChangeScenario(scenarioName);
105	        Habitat simulationHabitat = createHabitat(chosenHabitat, simulatorStepCounter, chosenClimateChangeScenario);
106	        if (getNumberOfPlants() + getNumberOfAnimals(animalsToCreate) > calculateFieldArea()) {
107	            errorThrower.throwMessage("Too many animals were added for this habitat, please reduce the number of animals and try again");
108	            return null;
109	        }
110	        view = new SimulatorView(DEFAULT_DEPTH, DEFAULT_WIDTH, handler);
111	        populateWithAnimals(animalsToCreate, field);
112	        populateWithPlants(field);
113	        Time timeObject = new Time(simulatorStepCounter, DEFAULT_START_TIME);
114	        return new Simulator(simulationHabitat, timeObject ,speciesToEvolveInSimulation, field, simulatorStepCounter, view);
115	    }
116	
117	    /**
118	     * Read data for the chosen habitat and create a habitat object appropriately.
119	     *
120	     * @param habitatName (String) The name of the chosen habitat.
121	     * @param simulatorStepCounter (SimulationStep) The created SimulationStep object for this simulation to be handed to the Habitat object.
122	     * @param climateChangeScenario (ClimateScenarios) The created ClimateScenarios enum to be handed to the Habitat object.
123	     * @return (Habitat) the created Habitat object.
124	     */
125	    private Habitat createHabitat (String habitatName, SimulationStep simulatorStepCounter, ClimateScenarios climateChangeScenario)
126	    {
127	        if (habitatName != null) {
128	            habitatReader.extractDataFor(habitatName);
129	            Habitat chosenHabitat = new Habitat(simulatorStepCounter, climateChangeScenario ,habitatReader.getSpringTemperatures(), habitatReader.getSummerTemperatures(), habitatReader.getAutumnTemperatures(), habitatReader.getWinterTemperatures());
130	            habitatPlantConcentration = habitatReader.getPlantConcentration();
131	            return chosenHabitat;
132	        }
133	        else {
134	            errorThrower.throwMessage("Habitat name was not specified successfully.");
135	            return null;
136	        }
137	    }
138	
139	    /**
140	     * Populate the simulation with the chosen animals.
141	     * First reading the data relating to each animal,
142	     * then creating and adding to the list of species the right number of each animal.
143	     *
144	     * @param animalsToCreate (HashMap<String, Integer>) The names and number of chosen animals.
145	     * @param field (Field) The field in which the animals will evolve.
146	     */
147	    private void populateWithAnimals(HashMap<String, Integer> animalsToCreate, Field field)
148	    {
149	        idxOfColorToUseNext = 0;
150	        Location freeLocationToPlaceAnimal;
151	
152	        for(String animalName : animalsToCreate.keySet()) {
153	            animalReader.extractDataFor(animalName);
154	            if (animalsToCreate.get(animalName) != 0)
155	            {
156	                // Retrieve appropriate data.
157	                String name = animalReader.getName();
158	                int maximumTemperature = animalReader.getMaximumTemperature();
159	                int minimumTemperature = animalReader.getMinimumTemperature();
160	                int maxAge = animalReader.getMaximumAge();
161	                int breedingAge = animalReader.getBreedingAge();
162	                double breedingProbability = animalReader.getBreedingProbability();
163	                int maxLitterSize = animalReader.getMaxLitterSize();
164	                int nutritionalValue = animalReader.getNutritionalValue();
165	                boolean hibernates = animalReader.canHibernate();
166	                boolean isNocturnal = animalReader.isNocturnal();
167	
168	                if (animalReader.isPredator()) {
169	                    // Predator object should be created, retrieving appropriate data.
170	                    int strength = animalReader.getStrength();
171	
172	                    // Creating the right number of Predator objects.
173	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
174	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
175	                        Predator newPredator = new Predator(strength, field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
176	                        speciesToEvolveInSimulation.add(newPredator);
177	                    }
178	                }
179	                else {
180	                    // Animal object should be created
181	                    // Creating the right number of Animal objects.
182	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
183	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
184	                        Animal newAnimal = new Animal(field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
185	                        speciesToEvolveInSimulation.add(newAnimal);
186	                    }
187	                }
188	
189	                // Setting the color for this species.
190	                view.setColor(name, listOfColorsForAnimals.get(idxOfColorToUseNext));
191	                idxOfColorToUseNext ++;
192	            }
193	        }
194	    }
195	
196	    /**
197	     * Create the chosen climate change scenario. Scenarios are pre-defined in the enum ClimateScenarios
198	     * as their functions can be changed to better approximate the real scenarios projected by the GIEC.
199	     *
200	     * @param scenarioName (String) The name of the scenario chosen by the user.
201	     * @return (ClimateScenarios) The created ClimateScenarios enum.
202	     */
203	    private ClimateScenarios createChosenClimateChangeScenario(String scenarioName)
204	    {
205	        return ClimateScenarios.fromLabel(scenarioName);
206	    }
207	
208	    /**
209	     * Find an available location for an object to be created in the simulation field.
210	     * The simulation is chosen at random and is changed if the randomly selected cell
211	     * already contains an object.
212	     *
213	     * @param field (Field) The simulation's field.
214	     * @return (Location) the available location found.
215	     */
216	    private Location findAvailableLocation(Field field)
217	    {
218	        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
219	        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
220	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
221	            randomWidth = rand.nextInt(DEFAULT_WIDTH);
222	            randomDepth = rand.nextInt(DEFAULT_DEPTH);
223	        }
224	        return new Location(randomDepth, randomWidth);
225	    }
226	
227	    /**
228	     * Calculate the area of the field to know the number of plants that should be created.
229	     *
230	     * @return (int) The field's area.
231	     */
232	    private int calculateFieldArea()
233	    {
234	        return DEFAULT_WIDTH * DEFAULT_DEPTH;
235	    }
236	
237	    /**
238	     * Populate the simulation with the appropriate number of plants.
239	     *
240	     * @param field (Field) The simulation's field.
241	     */
242	    private void populateWithPlants(Field field)
243	    {
244	        Location freeLocationToPlacePlant;
245	        plantReader.extractDataFor(DEFAULT_PLANT_NAME);
246	        String name = plantReader.getName();
247	        int maximumTemperature = plantReader.getMaximumTemperature();
248	        int minimumTemperature = plantReader.getMinimumTemperature();
249	        int nutritionalValue = plantReader.getNutritionalValue();
250	        double reproductionProbability = plantReader.getReproductionProbability();
251	        int maxHealth = plantReader.getMaxHealth();
252	        for (int i = 0; i< getNumberOfPlants(); i++) {
253	            freeLocationToPlacePlant = findAvailableLocation(field);
254	            Plant createdPlant = new Plant(field, freeLocationToPlacePlant, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability, maxHealth);
255	            speciesToEvolveInSimulation.add(createdPlant);
256	        }
257	        view.setColor(name, DEFAULT_PLANT_COLOR);
258	    }
259	
260	    /**
261	     * Calculate the total number of plants to be created.
262	     *
263	     * @return (int) the number of plants.
264	     */
265	    private int getNumberOfPlants()
266	    {
267	        int fieldArea = calculateFieldArea();
268	        return (int)(fieldArea * habitatPlantConcentration);
269	    }
270	
271	    /**
272	     * Calculate the total number of animals to be created.
273	     *
274	     * @return (int) the number of animals.
275	     */
276	    private int getNumberOfAnimals(HashMap<String, Integer> animalsToCreate)
277	    {
278	        int totalNumber = 0;
279	        for (String animalName : animalsToCreate.keySet()) {
280	            totalNumber += animalsToCreate.get(animalName);
281	        }
282	        return totalNumber;
283	    }
284	
