286	     * Populate the list of colors to use for animals with 25 colors. 25 animals can therefore be created
287	     * , other colors be added to implement more animal choices.
288	     */
289	    private void populateAnimalColors()
290	    {
291	        listOfColorsForAnimals.add(Color.decode("0xFF1493"));
292	        listOfColorsForAnimals.add(Color.decode("0xFFA500"));
