1	/**
2	 * This class reads from "plants.csv" the information about all the plants
3	 * that are available to be put in the simulation.
4	 *
5	 * @version 2022.02.28
6	 */
7	
8	public class PlantCSVReader extends CSVReader
9	{
10	    // Name of the file containing plant data.
11	    private static final String FILE_NAME = "plants.csv";
12	    // The plant's name.
13	    private String name;
14	    // The maximum temperature plant can survive to.
15	    private int maximumTemperature;
16	    // The minimum temperature plant can survive to.
17	    private int minimumTemperature;
18	    // The nutritional value brought when plant is eaten.
19	    private int nutritionalValue;
20	    // Probability to see plant reproduce.
21	    private double reproductionProbability;
22	    // The plant's maximum health.
23	    private int maxHealth;
24	    // Tool to alert user about any potential error.
25	    private ErrorThrower errorThrower;
26	    
27	    /**
28	     * Build a PlantCSVReader and initialize fields.
29	     */
30	    public PlantCSVReader ()
31	    {
32	        errorThrower = new ErrorThrower();
33	        resetParameters();
34	    }
35	
36	    /**
37	     * Populated fields with the data read from the files. This method overrides a method of the CSVReader parent class
38	     * and is therefore called after reading the data.
39	     *
40	     * @param extractedData (String[]) The data read.
41	     */
42	    protected void populateFields(String[] extractedData)
43	    {
44	        if (extractedData.length != 6) {
45	            errorThrower.throwMessage("Plant .csv issue, please restart.");
46	        }
47	        name                    = extractedData[0];
48	        maximumTemperature      = Integer.parseInt(extractedData[1]);
49	        minimumTemperature      = Integer.parseInt(extractedData[2]);
50	        nutritionalValue        = Integer.parseInt(extractedData[3]);
51	        reproductionProbability = Double.parseDouble(extractedData[4]);
52	        maxHealth               = Integer.parseInt(extractedData[5]);
53	    }
54	
55	    /**
56	     * Set all parameters back to initial values before reading data for another plant.
57	     */
58	    protected void resetParameters()
59	    {
60	        name = null;
61	        maximumTemperature = 0;
62	        minimumTemperature = 0;
63	        nutritionalValue = 0;
64	        reproductionProbability = 0;
65	        maxHealth =0;
66	    }
67	
68	    /**
69	     * @return (String) The name of the file containing plant data.
70	     */
71	    protected String getFileName() {
72	        return FILE_NAME;
73	    }
74	
75	    /**
76	     * @return (int) The plant's nutritional value.
77	     */
78	    public int getNutritionalValue() {
79	        return nutritionalValue;
80	    }
81	
82	    /**
83	     * @return (int) The minimum temperature a plant can survive to.
84	     */
85	    public int getMinimumTemperature() {
86	        return minimumTemperature;
87	    }
88	
89	    /**
90	     * @return (int) The maximum temperature a plant can survive to.
91	     */
92	    public int getMaximumTemperature() {
93	        return maximumTemperature;
94	    }
95	
96	    /**
97	     * @return (String) The plant's name.
98	     */
99	    public String getName() {
100	        return name;
101	    }
102	
103	    /**
104	     * @return (double) Probability that the plant reproduces.
105	     */
106	    public double getReproductionProbability() {
107	        return reproductionProbability;
108	    }
109	
110	    /**
111	     * @return (int) The plant's maximum health.
112	     */
113	    public int getMaxHealth() {
114	        return maxHealth;
115	    }
116	}

1	import java.util.Random;
2	
3	/**
4	 * Provide control over the randomization of the simulation. By using the shared, fixed-seed 
5	 * randomizer, repeated runs will perform exactly the same (which helps with testing). Set 
6	 * 'useShared' to false to get different random behaviour every time.
7	 *
8	 * @version 2016.02.29
9	 */
10	public class Randomizer
11	{
12	    // The default seed for control of randomization.
13	    private static final int SEED = 1111;
14	    // A shared Random object, if required.
15	    private static final Random rand = new Random(SEED);
16	    // Determine whether a shared random generator is to be provided.
17	    private static final boolean useShared = false;
18	
19	    /**
20	     * Constructor for objects of class Randomizer
21	     */
22	    public Randomizer()
23	    {
24	    }
25	
26	    /**
27	     * Provide a random generator.
28	     *
29	     * @return A random object.
30	     */
31	    public static Random getRandom()
32	    {
33	        if(useShared) {
34	            return rand;
35	        }
36	        else {
37	            return new Random();
38	        }
39	    }
40	    
41	    /**
42	     * Reset the randomization. This will have no effect if randomization is not through a shared Random generator.
43	     */
44	    public static void reset()
45	    {
46	        if(useShared) {
47	            rand.setSeed(SEED);
48	        }
49	    }
50	}
