1	/**
2	 * A simple class to keep track of and increment
3	 * the steps in the simulation.
4	 *
5	 * @version 2022.02.16
6	 */
7	public class SimulationStep
8	{
9	    private int currentStep;
10	
11	    /**
12	     * Construct a SimulationStep object starting with the given step.
13	     *
14	     * @param initialStep (int) The starting step number
15	     */
16	    public SimulationStep(int initialStep)
17	    {
18	        currentStep = initialStep;
19	    }
20	
21	    /**
22	     * Construct a SimulationStep object starting with step 0.
23	     */
24	    public SimulationStep()
25	    {
26	        currentStep = 0;
27	    }
28	
29	    /**
30	     * @return (int) The current step.
31	     */
32	    public int getCurrentStep()
33	    {
34	        return currentStep;
35	    }
36	
37	    /**
38	     * Increment the steps by one.
39	     */
40	    public void incStep()
41	    {
42	        currentStep++;
43	    }
44	
45	    /**
46	     * Reset the current step to 0.
47	     */
48	    public void reset()
49	    {
50	        currentStep = 0;
51	    }
52	}
