3	/**
4	 * A class representing plants in the simulation. It extends
5	 * the abstract class Species
6	 *
7	 * @version 2022.02.28
8	 */
9	public class Plant extends Species
10	{
11	    // The plant's maximum health
12	    private int maxHealth;
13	    // The probability that the plant's health grows
14	    private static final double GROWING_PROBABILITY = 0.1;
15	    // Keep track of the plant's health
16	    private int currentHealth;
17	    // true if the plant can regrow; reset each season change, cleared on wilt to prevent same-season re-emergence
18	    private boolean canRegrow;
19	    // true if plant appears dead due to temperature circumstances
20	    private boolean deadDueTemperature;
21	
22	    /**
23	     * Create an instance of Plant
24	     *
25	     * @param field (Field) The field currently occupied.
26	     * @param location (Location) The location within the field.
27	     * @param name (String) The name of the plant
28	     * @param maximumTemperature (int) The maximum temperature that the plant can withstand
29	     * @param minimumTemperature (int) The minimum temperature that the plant can withstand
30	     * @param nutritionalValue (int) The nutritional value given to the specie that eats this plant
31	     * @param reproductionProbability (double) The probability that this plant will reproduce
32	     * @param maxHealth (int) The plant's maximum health
33	     */
34	    public Plant(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxHealth)
35	    {
36	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
37	        this.maxHealth = maxHealth;
38	        currentHealth = maxHealth;
39	        canRegrow = true;
40	        deadDueTemperature = false;
41	    }
42	
43	    /**
44	     * Imitate a plant's step by doing the following:
45	     * 1) if the plant can't survive the temperature, then it dies
46	     * 2) else if the time is day:
47	     *      i) if the plant is dead, and it's spring, and the temperature is suitable,
48	     *         then grow back
49	     *      ii) else if the plant is alive, then
50	     *          a) increase max health by 1 if it lived for a year
51	     *          b) reproduce and grow
52	     *
53	     * @param newPlants (List<Species>) A list to return the new plants created.
54	     * @param isNight (boolean) true if it is night in the simulation
55	     * @param temperature (int) The current temperature of the simulation
56	     * @param yearPassed (boolean) True if a year has passed in the simulation
57	     * @param isSpring (boolean) True if the current season is spring
58	     * @param seasonChanged (boolean) True if the season just changed this step
59	     */
60	    public void act(List<Species> newPlants, boolean isNight, int temperature, boolean yearPassed, boolean isSpring, boolean seasonChanged)
61	    {
62	        if (seasonChanged) {
63	            canRegrow = true;
64	        }
65	        // 1)
66	        if (! deadDueTemperature && ! survivesTemperature(temperature))
67	        {
68	            wilt();
69	        }
70	        // 2)
71	        else if (! isNight)
72	        {
73	            // i)
74	            if (deadDueTemperature && survivesTemperature(temperature) && isSpring) {
75	                regrow();
76	            }
77	            // ii)
78	            else if (! deadDueTemperature) {
79	                // a)
80	                if (yearPassed) {
81	                    maxHealth++;
82	                }
83	                // b)
84	                reproduce(newPlants);
85	                grow();
86	            }
87	        }
88	    }
89	
90	    /**
91	     * Add a new plant in a free neighbouring location if the two
92	     * following conditions are met:
93	     * 1- The production probability meets the random number
94	     * 2- There is a free adjacent location.
95	     *
96	     * @param newPlants (list<Species>)A list to return the new plant
97	     */
98	    protected void reproduce(List<Species> newPlants)
99	    {
100	        if (rand.nextDouble() <= getReproductionProbability())
101	        {
102	            Field field = getField();
103	            if (field != null)
104	            {
105	                List<Location> free = field.getFreeAdjacentLocations(getLocation());
106	
107	                if (free.size() > 0) {
108	                    Location loc = free.remove(0);
109	                    Plant newPlant = new Plant(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxHealth);
110	                    newPlants.add(newPlant);
111	                }
112	            }
113	        }
114	    }
115	
116	    /**
117	     * The plant wilts due to temperature: it is removed from the field but remains in the
118	     * species list so it can regrow in spring. Unlike permanent death (when eaten), the
119	     * plant's alive state is unchanged and its field/location references are preserved.
120	     */
121	    private void wilt()
122	    {
123	        if(getLocation() != null) {
124	            deadDueTemperature = true;
125	            canRegrow = false; // prevent immediate regrowth next step
126	            getField().clear(getLocation());
127	        }
128	    }
129	
130	    /**
131	     * The dead plant is placed back in the field if its previous location is empty and can regrow, otherwise do nothing.
132	     * If it grows, then it grows back to full health.
133	     */
134	    private void regrow()
135	    {
136	        if(getField().getObjectAt(getLocation()) == null && canRegrow)   {
137	            deadDueTemperature = false;
138	            getField().place(this, getLocation());
139	            currentHealth = maxHealth;
140	        }
141	    }
142	
143	    /**
144	     * Increase the plant's health by one if the random number meets the growing probability
145	     */
146	    private void grow()
147	    {
148	        if (currentHealth < maxHealth && rand.nextDouble() <= GROWING_PROBABILITY) {
149	            currentHealth++;
150	        }
151	    }
152	
153	    /**
154	     * The effect of getting eaten by an animal.
155	     * Decrement currentHealth by one, and set dead if the current health is less than 1.
156	     */
157	    public void isEaten()
158	    {
159	        currentHealth--;
160	
161	        if (currentHealth <= 0)    {
162	            super.setDead();
163	        }
164	    }
165	
166	}
