248	    /**
249	     * Provide a graphical view of a rectangular field. This is a nested class (a class defined inside a class) which defines a
250	     * custom component for the user interface. This component displays the field.
251	     * This is rather advanced GUI stuff - you can ignore this for your project if you like.
252	     */
253	    class FieldView extends JPanel
254	    {
255	        private final int GRID_VIEW_SCALING_FACTOR = 6;
256	
257	        private int gridWidth, gridHeight;
258	        private int xScale, yScale;
259	        Dimension size;
260	        private Graphics g;
261	        private Image fieldImage;
262	
263	        /**
264	         * Create a new FieldView component.
265	         */
266	        public FieldView(int height, int width)
267	        {
268	            gridHeight = height;
269	            gridWidth = width;
270	            size = new Dimension(0, 0);
271	        }
272	
273	        /**
274	         * Tell the GUI manager how big we would like to be.
275	         */
276	        public Dimension getPreferredSize()
277	        {
278	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
279	                    gridHeight * GRID_VIEW_SCALING_FACTOR);
280	        }
281	
282	        /**
283	         * Prepare for a new round of painting. Since the component may be resized, compute the scaling factor again.
284	         */
285	        public void preparePaint()
286	        {
287	            if(! size.equals(getSize())) {  // if the size has changed...
288	                size = getSize();
289	                fieldImage = fieldView.createImage(size.width, size.height);
290	                g = fieldImage.getGraphics();
291	
292	                xScale = size.width / gridWidth;
293	                if(xScale < 1) {
294	                    xScale = GRID_VIEW_SCALING_FACTOR;
295	                }
296	                yScale = size.height / gridHeight;
297	                if(yScale < 1) {
298	                    yScale = GRID_VIEW_SCALING_FACTOR;
299	                }
300	            }
301	        }
302	
303	        /**
304	         * Paint on grid location on this field in a given color.
305	         */
306	        public void drawMark(int x, int y, Color color)
307	        {
308	            g.setColor(color);
309	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
310	        }
311	
312	        /**
313	         * The field view component needs to be redisplayed. Copy the internal image to screen.
314	         */
315	        public void paintComponent(Graphics g)
316	        {
317	            if(fieldImage != null) {
318	                Dimension currentSize = getSize();
319	                if(size.equals(currentSize)) {
320	                    g.drawImage(fieldImage, 0, 0, null);
321	                }
322	                else {
323	                    // Rescale the previous image.
324	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
325	                }
326	            }
327	        }
328	    }
329	}

1	import java.util.List;
2	import java.util.ArrayList;
3	import java.util.Iterator;
4	
5	/**
6	 * This is the main class of the simulation, as it connects all the other classes
7	 * and runs the simulation. In general, the classes simulate a habitat in which
8	 * there are preys who feed on plants, and predators who compete for the preys.
9	 *
10	 * @version 2022.02.28
11	 */
12	public class Simulator
13	{
14	    private static final int LONG_SIMULATION_STEP_COUNT = 2000;
15	    // List of species in the field.
16	    private List<Species> species;
17	    // The current state of the field.
18	    private Field field;
19	    // keep track of the simulation steps.
20	    private SimulationStep simStep;
21	    // A graphical view of the simulation.
22	    private SimulatorView view;
23	    // keep track of the time in the simulation
24	    private Time time;
25	    // the habitat of the simulation
26	    private Habitat simulationHabitat;
27	    private boolean simulationIsOn;
28	
29	    private static final int DEFAULT_DELAY = 0;
30	
31	    /**
32	     * Construct a simulation field with default size.
33	     */
34	    public Simulator(Habitat simulationHabitat, Time time, List<Species> speciesInSimulation, Field field, SimulationStep simulationStepCounter, SimulatorView simulatorView)
35	    {
36	        this.simulationHabitat = simulationHabitat;
37	        this.time = time;
38	        this.species = speciesInSimulation;
39	        this.field = field;
40	        this.simStep = simulationStepCounter;
41	        this.view = simulatorView;
42	        this.simulationIsOn = true;
43	
44	        view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
45	    }
46	
47	
48	    /**
49	     * Run the simulation from its current state for a reasonably long period set as a class constant.
50	     */
51	    public void runLongSimulation()
52	    {
53	        simulate(LONG_SIMULATION_STEP_COUNT);
54	    }
55	    
56	    public void runHundredSteps()
57	    {
58	        simulate(100);
59	    }
60	
61	    /**
62	     * Run the simulation from its current state for the given number of steps.
63	     * Stop before the given number of steps if it ceases to be viable.
64	     *
65	     * @param numSteps (int) The number of steps to run for.
66	     */
67	    public void simulate(int numSteps)
68	    {
69	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
70	            delay(DEFAULT_DELAY);
71	            simulateOneStep();
72	            // delay(200);   // uncomment this to run more slowly
73	        }
74	    }
75	
76	    /**
77	     * Run the simulation from its current state for a single step.
78	     * Iterate over the whole field updating the state of each specie.
79	     */
80	    public void simulateOneStep()
81	    {
82	        if (simulationIsOn) {
83	            simStep.incStep();
84	            simulationHabitat.habitatStep();
85	            time.timeStep();
86	
87	            // the following variables are added here to reduce method calls:
88	            boolean isSpring = simulationHabitat.getIsSpring();
89	            boolean isNight = time.getIsNight();
90	            int currentTemperature = simulationHabitat.getCurrentTemperature();
91	            boolean yearPassed = simulationHabitat.yearPassed();
92	            boolean seasonChanged = simulationHabitat.seasonJustChanged();
93	
94	            // Provide space for newborn species.
95	            List<Species> newSpecies = new ArrayList<>();
96	            // Let all species act.
97	            for(Iterator<Species> it = species.iterator(); it.hasNext(); )
98	            {
99	                Species specie = it.next();
100	                specie.act(newSpecies, isNight, currentTemperature, yearPassed, isSpring, seasonChanged);
101	                if(! specie.isAlive()) {
102	                    it.remove();
103	                }
104	            }
105	
106	            // Add the newly born species to the main lists.
107	            species.addAll(newSpecies);
108	            view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
109	        }
110	    }
111	
112	    /**
113	     * Reset the simulation to a starting position.
114	     */
115	    public void endSimulation()
116	    {
117	        simStep.reset();
118	        species.clear();
119	        simulationIsOn = false;
120	    }
121	
122	    /**
123	     * Pause for a given time.
124	     * @param millisec (int) The time to pause for, in milliseconds
125	     */
126	    private void delay(int millisec)
127	    {
128	        try {
129	            Thread.sleep(millisec);
130	        }
131	        catch (InterruptedException ie) {
132	            // wake up
133	        }
134	    }
135	}
