5	/**
6	 * The GUIHandler handles the GUI by switching between views and coordinating
7	 * all the GUI's interactions with the simulation's "backend".
8	 *
9	 * @version 2022.02.28
10	 */
11	public class GUIHandler
12	{
13	    private Initializer simulationInitializer;
14	    private Simulator simulatorOnDisplay;
15	    private JFrame currentFrame;
16	    private ArrayList<String> animalChoices;
17	    private ArrayList<String> habitatChoices;
18	    private ArrayList<String> scenarioChoices;
19	
20	    /**
21	     * Build a GUIHandler with appropriate lists of choices for animals, habitats, and climate change scenarios.
22	     *
23	     * @param animalChoices (ArrayList<String>) List of animal choices.
24	     * @param habitatChoices (ArrayList<String>) List of habitat choices.
25	     * @param scenarioChoices (ArrayList<String>) List of climate change scenario choices.
26	     */
27	    public GUIHandler (Initializer initializer, ArrayList<String> animalChoices, ArrayList<String> habitatChoices, ArrayList<String> scenarioChoices)
28	    {
29	        simulationInitializer = initializer;
30	        this.animalChoices = animalChoices;
31	        this.habitatChoices = habitatChoices;
32	        this.scenarioChoices = scenarioChoices;
33	        showMenuView();
34	    }
35	
36	    /**
37	     * Set the menuView as the view currently on screen. The menu view is the view
38	     * that allows the user to set their choices concerning the simulation to be run.
39	     */
40	    private void showMenuView()
41	    {
42	        MenuView menuViewMaker = new MenuView(this, animalChoices, habitatChoices, scenarioChoices);
43	        JFrame menuFrame = menuViewMaker.createAndShow();
44	        menuFrame.pack();
45	        menuFrame.setVisible(true);
46	        currentFrame = menuFrame;
47	    }
48	
49	    /**
50	     * Switch to simulator view. The actual creation of the simulator view
51	     * (which is automatically displayed at its creation) is done by the Initializer
52	     * but this method is crucial as it gives the Initializer the information needed
53	     * to create the simulation the user asked for and hides the MenuView currently on display.
54	     *
55	     * @param chosenHabitat (String) The name of the chosen habitat.
56	     * @param selectedAnimals (HashMap<String, Integer>) Key-pair associations of animal names and number of those animals to be created.
57	     * @param chosenScenario (String) The name of the chosen climate change scenario.
58	     */
59	    public void switchToSimulatorView(String chosenHabitat,HashMap<String, Integer> selectedAnimals,String chosenScenario)
60	    {
61	        simulatorOnDisplay = simulationInitializer.initializeSimulation(chosenHabitat, selectedAnimals, chosenScenario);
62	        if (simulatorOnDisplay != null) {
63	            currentFrame.setVisible(false);
64	        }
65	    }
66	
67	    /**
68	     * Switch to menu view. This method allows users to launch a new simulation
69	     * in the same "session". It ends the currently running simulation and creates a totally
70	     * new instance of MenuView to be displayed.
71	     */
72	    public void switchToMenuView()
73	    {
74	        simulatorOnDisplay.endSimulation();
75	        currentFrame.setVisible(false);
76	        showMenuView();
77	    }
78	
79	    /**
80	     * Launches a long simulation (number of steps defined in the Simulator class).
81	     */
82	    public void launchLongSimulation()
83	    {
84	        new Thread(simulatorOnDisplay::runLongSimulation).start();
85	    }
86	
87	    /**
88	     * Launches a simulation long of 100 steps, allowing user to
89	     * periodically examine the state of the running simulation.
90	     */
91	    public void runHundredSteps()
92	    {
93	        new Thread(simulatorOnDisplay::runHundredSteps).start();
94	    }
95	
96	    /**
97	     * Launches a single step of simulation, allowing user to
98	     * have even greater details on the species' behaviors.
99	     */
100	    public void runOneStep()
101	    {
102	        simulatorOnDisplay.simulate(1);
103	    }
104	}

1	import java.util.ArrayList;
2	import java.util.List;
3	
4	/**
5	 * A class representing shared characteristics of animals,
6	 * could be initialised for prey animals.
7	 *
8	 * @version 2022.02.28
9	 */
10	
11	public class Animal extends Species
12	{
13	    // Fields defining a special kind of animal, they can not be changed after initialization
14	
15	    // The age at which an animal can start to breed.
16	    private final int breedingAge;
17	    // The age to which an animal can live.
18	    private final int maxAge;
19	    // The maximum number of births at once.
20	    private final int maxLitterSize;
21	    // true if the animal's sex if female
22	    private final boolean isFemale;
23	    // true if the animal hibernates during cold temperatures
24	    private final boolean hibernates;
25	    // true if the animal is active at night
26	    private final boolean isNocturnal;
27	    // the number of steps that should pass until an animal in hibernation moves
28	    private static final int STAY_STEPS = 10;
29	    // foodLevel cap as a multiple of nutritional value — above this threshold the animal stops eating
30	    private static final double FOOD_LEVEL_FULL_MULTIPLIER = 1.5;
31	
32	    // Fields prone to change during the animal's life
33	
34	    // The animal's food level
35	    protected int foodLevel;
36	    // number of steps where the animal is in hibernation
37	    private int hiberSteps;
38	    // true if the animal is currently hibernating
39	    private boolean inHibernation;
40	    // The animal's age.
41	    private int age;
42	
43	    /**
44	     * Create a new animal with given specifications. An animal can be created with random age (or start at age 0) and
45	     * with a random foodLevel.
46	     *
47	     * @param field (Field) the field where the simulation takes place
48	     * @param location (Location) the Location at which the animal should appear
49	     * @param name (String) the animal's name (its species' name)
50	     * @param maximumTemperature (int) the maximum temperature the animal can survive to
51	     * @param minimumTemperature (int) the minimum temperature an animal can survive to
52	     * @param nutritionalValue (int) the animal's nutritional value
53	     * @param reproductionProbability (double) the probability that the animal reproduces at each step after a given minimum breeding age
54	     * @param maxAge (int) the animal's life expectancy
55	     * @param breedingAge (int) the age at which animal can start to reproduce
56	     * @param maxLitterSize (int) the maximum number of children the animal can have in one reproduction
57	     * @param randomAge (boolean) whether an animal should be created with a random age
58	     * @param hibernates (boolean) whether an animal is able to hibernate
59	     * @param isNocturnal (boolean) whether an animal is more active at night
60	     */
61	    public Animal(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize, boolean randomAge, boolean hibernates, boolean isNocturnal)
62	    {
63	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
64	
65	        this.breedingAge = breedingAge;
66	        this.maxAge = maxAge;
67	        this.maxLitterSize = maxLitterSize;
68	        this.isFemale = randomSex();
69	        this.hibernates = hibernates;
70	        this.isNocturnal = isNocturnal;
71	        // Default value is nutritionalValue to simulate the nutriment apart from the mother's milk/ other parental feeding.
72	        this.foodLevel = randomFoodLevel();
73	        inHibernation = false;
74	        hiberSteps = 0;
75	
76	        if (randomAge) {
77	            age = rand.nextInt(maxAge);
78	        } else {
79	            age = 0;
80	        }
81	    }
82	
83	    /**
84	     * Imitate an animal's step by doing the following:
85	     * 1) increment the animal's age if a year has passed.
86	     * 2) if the animal is alive, then:
87	     *      i) check if the animal should hibernate.
88	     *      ii) if the animal is in hibernation, then:
89	     *          a) if it passed STAY_STEPS steps without moving, then move and increment hunger.
90	     *          b) increment hiberSteps.
91	     *      iii) if the animal can't withstand the current temperature, then it dies.
92	     *      iv) if the animal is not in hibernation, then:
93	     *          a) if it is night and the animal is nocturnal, then move.
94	     *          b) if it is day, then all animals move and increment hunger.
95	     *
96	     * @param newSpecies (List<Species>) A list to receive newly born animals.
97	     * @param isNight (boolean) true if it is night in the simulation
98	     * @param temperature (int) the current temperature of the simulation
99	     * @param yearPassed true if a year has passed in the simulation
100	     */
101	    public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed, boolean isSpring, boolean seasonChanged)
102	    {
103	        // 1)
104	        if (yearPassed) {
105	            incrementAge();
106	        }
107	
108	        // 2)
109	        if(isAlive())
110	        {
111	            // i)
112	            checkHibernation(temperature);
113	            
114	            // ii)
115	            if (inHibernation)
116	            {
117	                // a)
118	                if (hiberSteps % STAY_STEPS == 0) {
119	                    makeMove(newSpecies);
120	                    if (isAlive()) {
121	                        incrementHunger();
122	                    }
123	                }
124	                // b)
125	                incrementHiberSteps();
126	            }
127	            // iii)
128	            else if (! survivesTemperature(temperature))
129	            {
130	                setDead();
131	            }
132	            // iv) All animals act during the day; nocturnal animals also act at night.
133	            else
134	            {
135	                if (!isNight || isNocturnal) {
136	                    makeMove(newSpecies);
137	                }
138	                if (!isNight && isAlive()) {
139	                    incrementHunger();
140	                }
141	            }
142	        }
143	    }
144	
145	    /**
146	     * An animal's movement. It first tries to reproduce, then to eat if a plant is in one of the neighboring cells and finally to move
147	     * if an adjacent cell is available. If no adjacent cell is available, it dies of overcrowding.
148	     *
149	     * @param newSpecies (List<Species>) A list to receive newly born animals.
150	     */
151	    protected void makeMove(List<Species> newSpecies)
152	    {
153	        ArrayList<Animal> neighboringAnimalsList = getNeighboringAnimalsList();
154	
155	        if (canReproduce(neighboringAnimalsList)) {
156	            reproduce(newSpecies);
157	        }
158	
159	        // Eats if it is possible
160	        if (isNotFull()) {
161	            findFoodAndEat();
162	        }
163	
164	        // Find a free location in adjacent cells
165	        Location newLocation = getField().freeAdjacentLocation(getLocation());
166	
167	        // See if it was possible to move.
168	        if(newLocation != null) {
169	            setLocation(newLocation);
170	        }
171	        else {
172	            // Overcrowding.
173	            setDead();
174	        }
175	    }
176	
177	    /**
178	     * Returns a list of animals located in neighboring cells.
179	     *
180	     * @return (ArrayList) list of neighboring animals
181	     */
182	    protected ArrayList<Animal> getNeighboringAnimalsList()
183	    {
184	        ArrayList<Animal> neighboringAnimals = new ArrayList<>();
185	        for (Location where : getField().adjacentLocations(getLocation())) {
186	            Species species = getField().getObjectAt(where);
187	            if (species instanceof Animal) {
188	                Animal neighboringAnimal = (Animal) species;
189	                if (neighboringAnimal.isAlive()) {
190	                    neighboringAnimals.add(neighboringAnimal);
191	                }
192	            }
193	        }
194	        return neighboringAnimals;
195	    }
196	
197	    /**
198	     * Increase the age. This could result in the animal's death.
199	     */
200	    protected void incrementAge()
201	    {
202	        age++;
203	        if(age > maxAge) {
204	            setDead();
205	        }
206	    }
207	
208	    /**
209	     * Make this animal more hungry. This could result in the animal's death.
210	     */
211	    protected void incrementHunger()
212	    {
213	        foodLevel--;
214	        if(foodLevel <= 0) {
215	            setDead();
216	        }
217	    }
218	    
219	    /**
220	     * @return (boolean) true if the animal is not full and therefore can eat and false if it is full.
221	     */
222	    protected boolean isNotFull()
223	    {
224	        return foodLevel < getNutritionalValue() * FOOD_LEVEL_FULL_MULTIPLIER;
225	    }
226	    
227	    /**
228	     * Increment hiberSteps by 1
229	     */
230	    protected void incrementHiberSteps()
231	    {
232	        hiberSteps++;
233	    }
234	
235	    /**
236	     * Look for plants adjacent to the current location.
237	     * Only the first plant is eaten.
238	     */
239	    private void findFoodAndEat()
240	    {
241	        for (Location where : getField().adjacentLocations(getLocation())) {
242	            Species species = getField().getObjectAt(where);
243	            if (species instanceof Plant) {
244	                Plant plant = (Plant) species;
245	                if (plant.isAlive()) {
246	                    plant.isEaten();
247	                    incrementFoodLevel(plant.getNutritionalValue());
248	                    break;
249	                }
250	            }
251	        }
252	    }
253	
254	    /**
255	     * If the animal is a female, check if a male of the same species is in one of the neighboring cells. If it is the case, animal is able to reproduce
256	     *  and should go to the cel where the male is.
257	     *  Note: The task of reproducing is handled only by females so that the same reproduction can not happen twice in the same simulator step.
258	     *
259	     * @param  neighboringAnimalsList (ArrayList<Animal>) Array List of the Animal objects located in neighboring cells.
260	     * @return (boolean) if animal can reproduce.
261	     *
262	     */
263	    protected boolean canReproduce(ArrayList<Animal> neighboringAnimalsList)
264	    {
265	        // Reproduction is handled only by females to prevent the same pair from reproducing twice per step.
266	        if (!this.isFemale || !canGiveBirth()) {
267	            return false;
268	        }
269	        for (Animal neighbor : neighboringAnimalsList) {
270	            if (!neighbor.isFemale && neighbor.getName().equals(this.getName())) {
271	                return true;
272	            }
273	        }
274	        return false;
275	    }
276	
277	    /**
278	     * Creates the appropriate number of animals of the same species. These new animals of course share the same features as their "parent"
279	     * except the sex which is randomized,  their age and foodLevel are not randomized.
280	     *
281	     * @param  speciesInSimulation (List<Species>) List of Species objects in the simulation for the newborns to be added to it.
282	     */
283	    protected void reproduce(List<Species> speciesInSimulation)
284	    {
285	        Field field = getField();
286	        if (field != null)
287	        {
288	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
289	            int births = numberOfBirths();
290	            for(int b = 0; b < births && free.size() > 0; b++) {
291	                Location loc = free.remove(0);
292	                Animal young = new Animal(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxAge, breedingAge, maxLitterSize,false, hibernates, isNocturnal);
293	                speciesInSimulation.add(young);
294	            }
295	        }
296	    }
297	
298	    /**
299	     * Returns a random boolean to randomize the sex of newborns.
300	     *
301	     * @return true if female, otherwise false (male)
302	     */
303	    private boolean randomSex()
304	    {
305	        return rand.nextBoolean();
306	    }
307	    
308	    /**
309	     * Return a random foodLevel more than the animal's nutritional value divided by half.
310	     *
311	     * @return (int) the foodLevel.
312	     */
313	    private int randomFoodLevel()
314	    {
315	        int lowBound = getNutritionalValue()/2;
316	        return rand.nextInt(lowBound) + lowBound;
317	    }
318	
319	    /**
320	     * Generate a number representing the number of births, if it can breed.
321	     *
322	     * @return (int) The number of births (can be zero).
323	     */
324	    protected int numberOfBirths()
325	    {
326	        int births = 0;
327	        if(canGiveBirth() && rand.nextDouble() <= getReproductionProbability()) {
328	            births = rand.nextInt(maxLitterSize) + 1;
329	        }
330	        return births;
331	    }
332	
333	    /**
334	     * An animal can give birth if it has reached the minimal breeding age.
335	     */
336	    protected boolean canGiveBirth()
337	    {
338	        return age >= breedingAge;
339	    }
340	
341	    /**
342	     * Check if the animal should be in hibernation.
343	     *
344	     * Change inHibernation to true if the animal can hibernate
345	     * and the current temperature is less than or equal the
346	     * minimum temperature of the animal + 5
347	     *
348	     * @param currentTemperature (int) the current temperature of the simulation
349	     */
350	    protected void checkHibernation(int currentTemperature)
351	    {
352	        if (hibernates && currentTemperature <= getMinimumTemperature() + 5)  {
353	            inHibernation = true;
354	        }
355	        else {
356	            inHibernation = false;
357	            hiberSteps = 0;
358	        }
359	    }
360	
361	    /**
362	     * @return (int) The maximum age to which an animal can live
363	     */
364	    protected int getMaxAge ()
365	    {
366	        return maxAge;
367	    }
368	
369	    /**
370	     * @return (int) The age at which an animal can start to breed
371	     */
372	    protected int getBreedingAge ()
373	    {
374	        return breedingAge;
375	    }
376	
377	    /**
378	     * @return (int) The maximum number of births at once
379	     */
380	    protected int getMaxLitterSize ()
381	    {
382	        return maxLitterSize;
383	    }
384	
385	    /**
386	     * @return (boolean) true if the animal hibernates
387	     */
388	    protected boolean getHibernates()
389	    {
390	        return hibernates;
391	    }
392	
393	    /**
394	     * @return (boolean) true if the animal is active at night
395	     */
396	    protected boolean getIsNocturnal()
397	    {
398	        return isNocturnal;
399	    }
400	
401	    /**
402	     * Increments the animal's food level by a given number (the nutritional value of the food he just ate).
403	     * It is public because a predator's food level can be incremented another predator in the case that it attacks it.
404	     *
405	     * @param value (int) the number to increment foodLevel by.
406	     */
407	    public void incrementFoodLevel(int value) {
408	        foodLevel += value;
409	    }
410	
411	}
