95	    /**
96	     * Method to be called on every step of the simulation for habitat conditions to be updated.
97	     *
98	     * 1) Increase the climate change effect if a year has passed
99	     * 2) Change the season if 'SEASON_CHANGE' steps have passed.
100	     * 3) Do the climate change effect on the new season
101	     * 4) Change the temperature each step
102	     */
103	    public void habitatStep()
104	    {
105	        int step = simStep.getCurrentStep();
106	
107	        // 1)
108	        if(yearPassed())
109	        {
110	            changeScenario.doClimateChange();
111	        }
112	
113	        // 2) & 3)
114	        if(step != 0 && step % SEASON_CHANGE == 0)
115	        {
116	            changeSeason();
117	            checkIsSpring();
118	            climateChangeEffect();
119	        }
120	
121	        // 4)
122	        randomizeTemperature();
123	    }
