130	     * @param summerValues (int[]) An integer array with two elements: [0]= summer aveTemperature, [1] = summer tempChange
131	     * @param autumnValues (int[]) An integer array with two elements: [0]= autumn aveTemperature, [1] = autumn tempChange
132	     * @param winterValues (int[]) An integer array with two elements: [0]= winter aveTemperature, [1] = winter tempChange
133	     */
134	    private void initialiseSeasons(int[] springValues, int[] summerValues, int[] autumnValues, int[] winterValues)
135	    {
136	        Season spring = new Season("spring", springValues[0], springValues[1]);
137	        Season summer = new Season("summer", summerValues[0], summerValues[1]);
138	        Season autumn = new Season("autumn", autumnValues[0], autumnValues[1]);
139	        Season winter = new Season("winter", winterValues[0], winterValues[1]);
140	
141	        // Initialise seasons and fill it
142	        seasons = new ArrayList<>();
143	        seasons.add(spring);
144	        seasons.add(summer);
145	        seasons.add(autumn);
146	        seasons.add(winter);
147	    }
