149	    /**
150	     * Change the current season according to the predefined order of seasons
151	     */
152	    private void changeSeason()
153	    {
154	        int seasonIndx = seasons.indexOf(currentSeason);
155	
156	        if(seasonIndx == seasons.size() -1) {
157	            currentSeason = seasons.get(0);
158	        }
159	        else {
160	            currentSeason = seasons.get(seasonIndx + 1);
161	        }
162	    }
