172	    /**
173	     * Change the current season's temperature randomly according to the season's tempChange field
174	     */
175	    private void randomizeTemperature()
176	    {
177	        int randomize = rand.nextInt(2);
178	        int change = rand.nextInt(currentSeason.getTempChange() + 1);
179	
180	        // make sure that the temperature doesn't go beyond the temperature upper limit
181	        if (randomize == 0 && (getCurrentTemperature() + change) <= currentSeason.getUpperLimitTemp()) {
182	            currentSeason.incrementCurrentTemperature(change);
183	        }
184	        // make sure that the temperature doesn't go below the temperature lower limit
185	        else if (randomize == 1 && (getCurrentTemperature() - change) >= currentSeason.getLowerLimitTemp()) {
186	            currentSeason.incrementCurrentTemperature(-change);
187	        }
188	    }
189	
190	    /**
191	     * Increase the season's average temperature by the climate change scenario's concreteChange
192	     */
193	    private void climateChangeEffect()
194	    {
195	        currentSeason.incAveTemperature(changeScenario.getClimateChangeEffect());
196	    }
