7	public class Time
8	{
9	    // true if it is night
10	    private boolean isNight;
11	    // keep track of the simulation steps.
12	    private SimulationStep simStep;
13	    // keep track of the hour of the day
14	    private int currentHour;
15	    // the number of steps before the type of day changes
16	    private static final int DAY_CHANGE = 1;
17	
18	    /**
19	     * Construct a Time object with the given parameters.
20	     *
21	     * @param simStep (SimulationStep) The object of SimulationStep to use for keeping track of the steps.
22	     * @param startNight (boolean) true if first iteration is night, false if day.
23	     */
24	    public Time(SimulationStep simStep, boolean startNight)
25	    {
26	        this.simStep = simStep;
27	        isNight = startNight;
28	
29	        if(isNight) {
30	            currentHour = 18;
31	        }
32	        else {
33	            currentHour = 6;
34	        }
35	    }
36	
37	    /**
38	     * @return (boolean) true if night, false otherwise.
39	     */
40	    public boolean getIsNight()
41	    {
42	        return isNight;
43	    }
44	
45	    /**
46	     * Create a String indicating night or day and the specific hour.
47	     *
48	     * @return (String) A String with the time's full information.
49	     */
50	    public String timeString()
51	    {
52	        String tString = "";
53	
54	        if(isNight) {
55	            tString += "Night \t";
56	        }
57	        else {
58	            tString += "Day \t";
59	        }
60	
61	        tString += "(" + getHourDisplay() + ")";
62	
63	        return tString;
64	    }
65	
66	    /**
67	     * Change the day status if 'CHANGE_STEPS' steps have passed, and increment the hours.
68	     */
69	    public void timeStep()
70	    {
71	        int step = simStep.getCurrentStep();
72	
73	        if(step != 0 && (step+1) % DAY_CHANGE == 0) { // step+1 because step starts with 0
74	            toggleIsNight();
75	        }
76	
77	        incHour();
78	    }
79	
80	    /**
81	     * Change the current status of the time.
82	     */
83	    private void toggleIsNight()
84	    {
85	        isNight = ! isNight;
86	    }
87	
88	    /**
89	     * Increment the hours to go through the day evenly.
90	     */
91	    private void incHour()
92	    {
93	        currentHour = (currentHour + (24 / (DAY_CHANGE * 2))) % 24;
94	    }
95	
96	    /**
97	     * Create a string displaying time in 24-hour style.
98	     *
99	     * @return (String)a String holding the current time.
100	     */
101	    private String getHourDisplay()
102	    {
103	        if(currentHour < 10)
104	        {
105	            return "0" + currentHour + ":00";
106	        }
107	
108	        return currentHour + ":00";
109	    }
110	}
